from pathlib import Path
import re, json

files = [
    'assets/uploads/f1494f0d_【开题报告准备脉路】.md',
    'assets/uploads/ae04a4a8_【开题报告】.md',
    'assets/uploads/b807daff_【开题报告】.md',
]
res = {}
for fp in files:
    text = Path(fp).read_text(encoding='utf-8')
    lines = text.splitlines()
    # collect markdown headings and numbered lines
    picks = []
    for ln in lines:
        s = ln.strip()
        if not s:
            continue
        if s.startswith('#') or re.match(r'^(\d+(\.\d+)*|[一二三四五六七八九十]+[、.])', s) or '研究' in s or '技术路线' in s or '开题报告' in s:
            picks.append(s)
    res[fp] = {
        'chars': len(text),
        'lines': len(lines),
        'sample_picks': picks[:80]
    }
print(json.dumps(res, ensure_ascii=False, indent=2))

from pathlib import Path
from zipfile import ZipFile
import xml.etree.ElementTree as ET
import json

path = Path('assets/uploads/fde1237c_开题报告-颜雍颀(1).docx')
ns = {'w': 'http://schemas.openxmlformats.org/wordprocessingml/2006/main'}
with ZipFile(path) as z:
    xml = z.read('word/document.xml')
root = ET.fromstring(xml)
paras=[]
for p in root.findall('.//w:p', ns):
    texts=[t.text for t in p.findall('.//w:t', ns) if t.text]
    if texts:
        paras.append(''.join(texts).strip())
headings = ['5.1 Characterization of the Co3O4-base Catalyst','5.2 SMX degradation performance of Co3O4-based catalyst','5.2.1 Degradation Efficiency of M-Co3O4','5.2.2 Degradation Efficiency of Ce-Co3O4 at Varying Ce Loadings','5.3 Research Schedule']
out = {}
for h in headings:
    try:
        idx = paras.index(h)
        out[h] = paras[idx:idx+25]
    except ValueError:
        out[h] = ['NOT FOUND']
print(json.dumps(out, ensure_ascii=False, indent=2))
